+import * as ethersModule from 'ethers';
+import type {
+  AbstractSigner,
+  BigNumberish,
+  ContractRunner,
+  EventLog,
+  Log,
+  TransactionReceipt,
+  TransactionResponse,
+} from 'ethers';
+
+type BigNumberValue =
+  | BigNumber
+  | bigint
+  | boolean
+  | number
+  | string
+  | { _hex?: string; hex?: string; toBigInt?: () => bigint; toString: () => string };
+
+const toEvenHex = (value: bigint) => {
+  const sign = value < 0n ? '-' : '';
+  const absolute = value < 0n ? -value : value;
+  const hex = absolute.toString(16);
+  return `${sign}0x${hex.length % 2 === 0 ? hex : `0${hex}`}`;
+};
+
+export class BigNumber {
+  readonly _hex: string;
+
+  readonly _isBigNumber = true;
+
+  private constructor(private readonly value: bigint) {
+    this._hex = toEvenHex(value);
+  }
+
+  static from(value: BigNumberValue): BigNumber {
+    if (value instanceof BigNumber) return value;
+    if (typeof value === 'bigint') return new BigNumber(value);
+    if (typeof value === 'boolean') return new BigNumber(value ? 1n : 0n);
+    if (typeof value === 'number') return new BigNumber(BigInt(value));
+    if (typeof value === 'string') return new BigNumber(BigInt(value));
+    if (typeof value.toBigInt === 'function') return new BigNumber(value.toBigInt());
+    if (value._hex ?? value.hex) return new BigNumber(BigInt(value._hex ?? value.hex ?? '0'));
+    return new BigNumber(BigInt(value.toString()));
+  }
+
+  static isBigNumber(value: unknown): value is BigNumber {
+    return value instanceof BigNumber || Boolean((value as BigNumber)?._isBigNumber);
+  }
+
+  add(value: BigNumberValue): BigNumber {
+    return new BigNumber(this.value + BigNumber.from(value).value);
+  }
+
+  sub(value: BigNumberValue): BigNumber {
+    return new BigNumber(this.value - BigNumber.from(value).value);
+  }
+
+  gte(value: BigNumberValue): boolean {
+    return this.value >= BigNumber.from(value).value;
+  }
+
+  eq(value: BigNumberValue): boolean {
+    return this.value === BigNumber.from(value).value;
+  }
+
+  toBigInt(): bigint {
+    return this.value;
+  }
+
+  toHexString(): string {
+    return this._hex;
+  }
+
+  toString(): string {
+    return this.value.toString();
+  }
+
+  toJSON() {
+    return { type: 'BigNumber', hex: this._hex };
+  }
+}
+
+const hexToUint8Array = (hex: string) => {
+  const withoutPrefix = hex.replace(/^0x/, '');
+  const padded =
+    withoutPrefix.length % 2 === 0 ? withoutPrefix : `0${withoutPrefix}`;
+  const matchArray = padded.match(/.{2}/g);
+  return new Uint8Array(matchArray?.map((n) => Number.parseInt(n, 16)) ?? []);
+};
+
+const decodeBase58 = (value: string) => {
+  const bigint = ethersModule.decodeBase58(value);
+  const leadingZeroes = value.match(/^1*/)?.[0].length ?? 0;
+  const hex = `${'00'.repeat(leadingZeroes)}${bigint.toString(16)}`;
+  return hexToUint8Array(hex);
+};
+
+const providers = {
+  AlchemyProvider: ethersModule.AlchemyProvider,
+  BrowserProvider: ethersModule.BrowserProvider,
+  CloudflareProvider: ethersModule.CloudflareProvider,
+  EtherscanProvider: ethersModule.EtherscanProvider,
+  FallbackProvider: ethersModule.FallbackProvider,
+  InfuraProvider: ethersModule.InfuraProvider,
+  JsonRpcProvider: ethersModule.JsonRpcProvider,
+  JsonRpcSigner: ethersModule.JsonRpcSigner,
+  WebSocketProvider: ethersModule.WebSocketProvider,
+  getDefaultProvider: ethersModule.getDefaultProvider,
+};
+
+const utils = {
+  Interface: ethersModule.Interface,
+  arrayify: ethersModule.getBytes,
+  base58: { decode: decodeBase58 },
+  formatEther: ethersModule.formatEther,
+  formatUnits: ethersModule.formatUnits,
+  getAddress: ethersModule.getAddress,
+  hexlify: ethersModule.hexlify,
+  id: ethersModule.id,
+  isAddress: ethersModule.isAddress,
+  keccak256: ethersModule.keccak256,
+  parseEther: (value: string) => BigNumber.from(ethersModule.parseEther(value)),
+  parseUnits: (value: string, unit?: string | number) =>
+    BigNumber.from(ethersModule.parseUnits(value, unit)),
+  sha256: ethersModule.sha256,
+  solidityKeccak256: ethersModule.solidityPackedKeccak256,
+  toUtf8Bytes: ethersModule.toUtf8Bytes,
+};
+
+const moduleWithLegacyExports = ethersModule as typeof ethersModule & {
+  BigNumber: typeof BigNumber;
+  providers: typeof providers;
+  utils: typeof utils;
+};
+
+const ethersNamespace = ethersModule.ethers as typeof ethersModule.ethers & {
+  BigNumber: typeof BigNumber;
+  providers: typeof providers;
+  utils: typeof utils;
+};
+
+moduleWithLegacyExports.BigNumber ??= BigNumber;
+moduleWithLegacyExports.providers ??= providers;
+moduleWithLegacyExports.utils ??= utils;
+ethersNamespace.BigNumber ??= BigNumber;
+ethersNamespace.providers ??= providers;
+ethersNamespace.utils ??= utils;
+
+export const ethers = ethersNamespace;
+export const Contract = ethersModule.Contract;
+export const Interface = ethersModule.Interface;
+export const VoidSigner = ethersModule.VoidSigner;
+export const Wallet = ethersModule.Wallet;
+export const getDefaultProvider = ethersModule.getDefaultProvider;
+export { providers, utils };
+
+export type Signer = AbstractSigner;
+export type Provider = ContractRunner;
+export type ContractReceipt = TransactionReceipt;
+export type ContractTransaction = TransactionResponse;
+export type Event = EventLog | Log;
+export type EventFilter = ethersModule.EventFilter;
+export type Overrides = ethersModule.Overrides;
+export type CallOverrides = ethersModule.TransactionRequest;
+export type PayableOverrides = ethersModule.TransactionRequest;
+export type PopulatedTransaction = ethersModule.TransactionRequest;
+export type BigNumberish = BigNumberish;
+export type BytesLike = ethersModule.BytesLike;
+export type ContractInterface = ethersModule.InterfaceAbi;
+
+export default moduleWithLegacyExports;
