const toEvenHex = (value: bigint) => {
  const sign = value < 0n ? '-' : '';
  const absolute = value < 0n ? -value : value;
  const hex = absolute.toString(16);
  return `${sign}0x${hex.length % 2 === 0 ? hex : `0${hex}`}`;
};

export class BigNumber {
  readonly _hex: string;

  readonly _isBigNumber = true;

  private constructor(private readonly value: bigint) {
    this._hex = toEvenHex(value);
  }

  static from(value: BigNumberValue): BigNumber {
    if (value instanceof BigNumber) return value;
    if (typeof value === 'bigint') return new BigNumber(value);
    if (typeof value === 'boolean') return new BigNumber(value ? 1n : 0n);
    if (typeof value === 'number') return new BigNumber(BigInt(value));
    if (typeof value === 'string') return new BigNumber(BigInt(value));
    if (typeof value.toBigInt === 'function')
      return new BigNumber(value.toBigInt());
    if (value._hex ?? value.hex)
      return new BigNumber(BigInt(value._hex ?? value.hex ?? '0'));
    return new BigNumber(BigInt(value.toString()));
  }

  static isBigNumber(value: unknown): value is BigNumber {
    return (
      value instanceof BigNumber || Boolean((value as BigNumber)?._isBigNumber)
    );
  }

  add(value: BigNumberValue): BigNumber {
